        return out
    h, w = len(grid), len(grid[0])
    upper = [(r, c) for r in range(barrier) for c, value in enumerate(grid[r]) if value == 4]
    lower = [(r, c) for r in range(barrier + 2, h) for c, value in enumerate(grid[r]) if value == 4]
    for r, c in upper + lower:
        out[r][c] = 0
    for r, c in upper:
        nr = r + 1
        out[nr][c] = 4
        if nr == barrier - 1:
            d = 1
            while nr - d >= 0:
                rr = nr - d
                for cc in (c - d, c + d):
                    if 0 <= cc < w:
                        out[rr][cc] = 4
                d += 1
    for r, c in lower:
        out[r - 1][c] = 4
    return out

